export default pattern<
  SignalPropagationAtlasInput,
  SignalPropagationAtlasOutput
>(({
  input,
  output,
}) => {
  const state = new Writable<IframeStateData>(DEFAULT_STATE);
  const { table } = cfSqlite;
  const iframeDatabase0Tables = {
    ["atlas_bookmarks"]: table({
      ["id"]: "text primary key",
      ["observation_id"]: "text not null",
      ["note"]: "text not null",
      ["created_at"]: "integer not null",
    }),
    ["atlas_hypotheses"]: table({
      ["id"]: "text primary key",
      ["title"]: "text not null",
      ["narrative"]: "text not null",
      ["status"]: "text not null",
      ["created_at"]: "integer not null",
    }),
  };
  const iframeDatabase0: PerUser<SqliteDb> = sqliteDatabase({
    tables: iframeDatabase0Tables,
  });
  const iframeInput = input ?? DEFAULT_INPUT;
  const context = IframeContext({
    input: iframeInput,
    state,
    output,
    ["personalAtlas"]: iframeDatabase0,
  });

  return {
    [NAME]: "Signal Propagation Atlas",
    [UI]: (
      <div style={{ width: "100%", height: "100vh" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
            ["personalAtlas"]: "sqlite",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
